void main() {
  vec2 p = (uv - vec2(0.5, horizon - 0.12)) * vec2(iResolution.x / iResolution.y, 1.0);
  float disc = step(length(p), sun_size);
  float y = max(p.y / sun_size + 0.15, 0.0);
  float bands = step(0.5 * y, fract(y * 4.0 - iTime * 0.3));
  gl_FragColor = vec4(vec3(disc * bands), 1.0);
}

void main() {
  vec2 px = radius / iResolution.xy;
  float sum = 0.0;
  for (int x = -2; x <= 2; x++) {
    for (int y = -2; y <= 2; y++) {
      sum += texture2D(iChannel0, uv + vec2(float(x), float(y)) * px).r;
    }
  }
  gl_FragColor = vec4(vec3(sum / 25.0), 1.0);
}

void main() {
  vec2 cell = abs(fract(uv * cells) - 0.5);
  gl_FragColor = vec4(vec3(smoothstep(0.42, 0.48, max(cell.x, cell.y))), 1.0);
}

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec3 col = texture2D(iChannel0, uv).rgb;
  float n = hash(floor(uv * iResolution.xy) + floor(iTime * 12.0));
  gl_FragColor = vec4(col * (1.0 - amount * n), 1.0);
}
